   if(modifier&&event.key.toLowerCase()==='z'){event.preventDefault();travel(event.shiftKey);}
   else if(modifier&&event.key.toLowerCase()==='y'){event.preventDefault();travel(true);}
   else if(event.key==='Escape')setSelected(null);
   else if((event.key==='Delete'||event.key==='Backspace')&&selected&&page){event.preventDefault();operate({type:'delete-overlay',pageId:page.id,overlayId:selected});setSelected(null);}
   else if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(event.key)&&selected&&page&&!actionBusy){const item=page.overlays.find(value=>value.id===selected);if(item){event.preventDefault();const step=event.shiftKey?10:1;operate({type:'update-overlay',pageId:page.id,overlayId:item.id,patch:dragPdfOverlay(item,page,{x:0,y:0},{x:event.key==='ArrowLeft'?-step:event.key==='ArrowRight'?step:0,y:event.key==='ArrowUp'?-step:event.key==='ArrowDown'?step:0},'move')});}}
